      i = j + 1;
      continue;
    }

    if (c === '}') {
      throw new UriTemplateError(`unexpected '}' at ${i}`, i);
    }

    literalBuf += c;
    i += 1;
  }

  if (literalBuf) parts.push({ type: 'literal', value: literalBuf });

  return parts;
}
